/**
 * engine-server/pipeline/evolution-loop.ts — M3 进化闭环最小实现（V1.2 第三阶段）
 *
 * 不依赖 GBK 编码损坏的旧 evolution/ 文件。
 * 基于 schema-bridge.ts 和 collaboration-collector.ts 从头构建。
 *
 * 进化流程：
 * 1. 采集运行时协作信号（collaboration-collector）
 * 2. 信号超过阈值 → 生成模式变体
 * 3. 变体写入 evolution-overrides.json（红线：不写 src/）
 * 4. 下次管道调用时合并覆盖层
 *
 * @packageDocumentation
 */
import type { EvolutionOverride, EvolutionOverridesFile } from './schema-bridge';
import type { CollaborationModeBlue, BlueprintFeedbackRequest } from '../types';
export declare function loadOverrides(): EvolutionOverridesFile;
export declare function saveOverrides(file: EvolutionOverridesFile): void;
/**
 * 将 evolution-overrides.json 中已合并(merged=true)的覆盖条目写入弹药库，
 * 作为"组织进化弹药"供后续管道调用的 Phase B 参考。
 *
 * 使用迭代替换逻辑：
 * - 如果弹药库中已有相同 id 的条目，跳过（只写一次）
 * - 如果没有，追加
 *
 * 这样已验证的进化变体逐次积累到弹药库中，形成持续进化的知识体系。
 *
 * @returns 本次新增的条目数
 */
export declare function writeOverridesAsOrgAmmo(blueprintId: string): number;
/**
 * 将 evolution-overrides.json 合并到运行时 CollaborationModeBlue。
 * 覆盖层中 merged=true 的条目直接应用，pending 的条目仅在标记为实验组时应用。
 */
export declare function applyOverridesToMode(mode: CollaborationModeBlue, experimentGroup?: string): CollaborationModeBlue;
/**
 * 消费 S2 用户反馈信号，更新推断置信度。
 *
 * 对每个被修改/删除的配置项，如果它来自某个 inferred 推断，
 * 降低该推断的 confidence，写入 evolution-overrides.json。
 */
export declare function consumeFeedback(feedback: BlueprintFeedbackRequest): number;
export interface EvolutionLoopResult {
    /** 是否产生了新变体 */
    newVariants: boolean;
    /** 产生的覆盖条目 */
    newOverrides: EvolutionOverride[];
    /** 当前所有覆盖 */
    allOverrides: EvolutionOverridesFile;
    /** 日志 */
    log: string[];
}
/**
 * 采集信号、生成变体、写入覆盖层。
 * 应在每次 Blueprint 生成后调用（异步，不阻塞管道返回）。
 */
export declare function runEvolutionLoop(currentMode: string, blueprintId: string): EvolutionLoopResult;
/**
 * 将进化循环日志注入 BlueprintDTO notes
 */
export declare function injectEvolutionNotes(result: EvolutionLoopResult, notes: string[]): void;
